// ============================================================================
// JSLAB_PhaseDisparityExporter.cpp
//
// Purpose:
//   Export the GLOBAL (absolute, unwrapped) PHASE MAPS produced during the
//   phase-shift + multi-frequency heterodyne DECODING stage, together with
//   the DISPARITY MAP generated by the stereo matching stage of the V2
//   epipolar reconstructor.
//
//   The pipeline is identical to rebuild_v8() in main.cpp:
//     setImages -> startCalculate(phase) [global phase, CV_64FC1]
//               -> getOrderMap(k)        [fringe order,  CV_32SC1]
//               -> getModulationMap(mod) [modulation,    CV_64FC1]
//     setData(lphase, rphase, l_k, r_k, l_mod, freq0)
//     startCalculate(xyz, P)
//     getDisparityMap(disp)              [sub-pixel disparity, CV_64FC1]
//
//   For every input group it saves into out_dir:
//     - phase_left_global.png  / phase_right_global.png  (pseudo-colored JET)
//     - phase_left_global.raw  / phase_right_global.raw  (raw CV_64FC1 data,
//       row-major doubles; load in Matlab with:
//       fid=fopen('xxx.raw','rb'); d=fread(fid,inf,'double');
//       d=reshape(d,cols,rows)'; fclose(fid);)
//     - disparity.png          (pseudo-colored, |disp| visualized; invalid
//       pixels black)
//     - disparity.raw          (raw CV_64FC1 data, ORIGINAL SIGNED values)
//     - *.info.txt             (rows / cols / type)
//
//   NOTE on the disparity sign: depending on the calibration, stereoMatch()
//   may output NEGATIVE disparities (disp = j - best_jR when the right
//   rectified image is shifted to the right). The validity mask therefore
//   uses |disp| > 0, and the PNG visualizes |disp|; the .raw file keeps the
//   signed values so the sign is never lost.
//
//   Pixels whose modulation is below the threshold (or whose disparity is
//   invalid) are painted black so unreliable regions are easy to inspect.
// ============================================================================

#include "JSLAB_PhaseShiftDecoder.h"
#include "JSLAB_PhaseEpipolarReconstructor_V2.h"
#include "JSLAB_StereoCalibParams_V1.h"

#include <opencv2/core.hpp>
#include <opencv2/imgproc.hpp>
#include <opencv2/imgcodecs.hpp>

#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <cmath>
#include <sys/stat.h>
#include <direct.h>

// ----------------------------------------------------------------------------
// mkdir all missing levels of a path (same helper as main.cpp)
// ----------------------------------------------------------------------------
static void ensure_dir(const std::string& path)
{
	if (path.empty()) return;
	std::string cur;
	cur.reserve(path.size());
	for (size_t i = 0; i < path.size(); ++i) {
		const char c = path[i];
		cur.push_back(c);
		if (c == '\\' || c == '/' || i + 1 == path.size()) {
			if (cur.size() == 2 && cur[1] == ':') continue; // drive root
			if (cur == "\\" || cur == "/") continue;
			struct _stat st;
			if (_stat(cur.c_str(), &st) != 0) {
				_mkdir(cur.c_str());
			}
		}
	}
}

// ----------------------------------------------------------------------------
// Save a CV_64FC1 map as a pseudo-colored PNG.
// Pixels where valid_mask == 0 are painted black.
// ----------------------------------------------------------------------------
static bool savePseudoColorMap(const cv::Mat& data,
                               const cv::Mat& valid_mask,
                               const std::string& png_path,
                               const std::string& title)
{
	if (data.empty() || data.type() != CV_64FC1) {
		std::cout << "[PhaseDisparityExporter] Cannot visualize " << title
		          << ": empty or non-CV_64FC1 map." << std::endl;
		return false;
	}

	double mn = 0.0, mx = 0.0;
	cv::minMaxLoc(data, &mn, &mx);
	if (mx - mn < 1e-12) mx = mn + 1.0; // guard against constant maps

	cv::Mat vis8, color;
	cv::normalize(data, vis8, 0, 255, cv::NORM_MINMAX, CV_8UC1);
	cv::applyColorMap(vis8, color, cv::COLORMAP_JET);

	if (!valid_mask.empty()) {
		cv::Mat invalid;
		cv::bitwise_not(valid_mask, invalid);
		color.setTo(cv::Scalar(0, 0, 0), invalid);
	}

	const bool ok = cv::imwrite(png_path, color);
	std::cout << "[PhaseDisparityExporter] Saved " << title << " -> " << png_path
	          << " (range " << mn << " .. " << mx << ")" << std::endl;
	return ok;
}

// ----------------------------------------------------------------------------
// Save a CV_64FC1 map as raw row-major doubles + an info file.
// ----------------------------------------------------------------------------
static bool saveRaw64F(const cv::Mat& data,
                       const std::string& raw_path,
                       const std::string& info_path)
{
	if (data.empty() || data.type() != CV_64FC1) return false;

	std::ofstream raw(raw_path, std::ios::binary);
	if (!raw.is_open()) return false;
	for (int r = 0; r < data.rows; ++r) {
		raw.write(reinterpret_cast<const char*>(data.ptr<double>(r)),
		          static_cast<std::streamsize>(data.cols * sizeof(double)));
	}
	raw.close();

	std::ofstream info(info_path);
	if (info.is_open()) {
		info << "rows " << data.rows << "\n"
		     << "cols " << data.cols << "\n"
		     << "type CV_64FC1 (double)\n"
		     << "layout row-major, one double per pixel\n"
		     << "rows/cols written on the FIRST line as 'rows cols' for convenience\n";
		info.close();
	}
	std::cout << "[PhaseDisparityExporter] Saved raw 64F data -> " << raw_path
	          << std::endl;
	return true;
}

// ----------------------------------------------------------------------------
// Main entry:
//   Decode the global (absolute) phase maps of one phase-shift image group,
//   run the stereo reconstruction, and export phase maps + disparity map.
//
//   pathL / pathR     : folders containing 1..N.bmp (N = sum of shift_num)
//   calib_xml_path    : stereo calibration XML (V1 format)
//   out_dir           : output folder (created if missing)
//   config            : decoder configuration (freq[3], shift_num[3],
//                       modulation_threshold, ...)
//
// Returns true on success.
// ----------------------------------------------------------------------------
bool exportPhaseAndDisparityMaps(const std::string& pathL,
                                 const std::string& pathR,
                                 const std::string& calib_xml_path,
                                 const std::string& out_dir,
                                 const JSLAB_PhaseShiftDecoder::Config& config)
{
	ensure_dir(out_dir);

	const int img_num = config.shift_num[0] +
	                    config.shift_num[1] +
	                    config.shift_num[2];

	// ---- 1. Load the phase-shift image group (L and R) ----
	std::vector<cv::Mat> limgs, rimgs;
	limgs.reserve(img_num);
	rimgs.reserve(img_num);
	for (int i = 0; i < img_num; ++i) {
		const std::string name = std::to_string(i + 1) + ".bmp";
		const cv::Mat limg = cv::imread(pathL + name, cv::IMREAD_GRAYSCALE);
		const cv::Mat rimg = cv::imread(pathR + name, cv::IMREAD_GRAYSCALE);
		if (limg.empty() || rimg.empty()) {
			std::cout << "[PhaseDisparityExporter] ERROR: failed to read image #"
			          << (i + 1) << " -> " << (pathL + name) << std::endl;
			return false;
		}
		limgs.push_back(limg);
		rimgs.push_back(rimg);
	}
	std::cout << "[PhaseDisparityExporter] Loaded " << img_num
	          << " phase-shift images per camera." << std::endl;

	// ---- 2. Decode the GLOBAL (absolute) phase maps ----
	auto phase_shift_decode =
		JSLAB_PhaseShiftDecoder::create(config, JSLAB_PhaseShiftDecoder::Version::V2);

	std::cout << "[PhaseDisparityExporter] Decoding LEFT global phase..." << std::endl;
	cv::Mat lphase, l_k, l_mod;
	phase_shift_decode->setImages(limgs);
	phase_shift_decode->startCalculate(lphase);  // global phase (CV_64FC1)
	phase_shift_decode->getOrderMap(l_k);        // fringe order  (CV_32SC1)
	phase_shift_decode->getModulationMap(l_mod); // modulation   (CV_64FC1)

	std::cout << "[PhaseDisparityExporter] Decoding RIGHT global phase..." << std::endl;
	cv::Mat rphase, r_k, r_mod;
	phase_shift_decode->setImages(rimgs);
	phase_shift_decode->startCalculate(rphase);
	phase_shift_decode->getOrderMap(r_k);
	phase_shift_decode->getModulationMap(r_mod);

	// ---- 3. Export the global phase maps ----
	const cv::Mat l_valid = l_mod > config.modulation_threshold;
	const cv::Mat r_valid = r_mod > config.modulation_threshold;

	savePseudoColorMap(lphase, l_valid, out_dir + "phase_left_global.png",
	                   "Left Global Phase Map");
	savePseudoColorMap(rphase, r_valid, out_dir + "phase_right_global.png",
	                   "Right Global Phase Map");
	saveRaw64F(lphase, out_dir + "phase_left_global.raw",
	           out_dir + "phase_left_global.info.txt");
	saveRaw64F(rphase, out_dir + "phase_right_global.raw",
	           out_dir + "phase_right_global.info.txt");

	// ---- 4. Stereo reconstruction (same pipeline as rebuild_v8) ----
	JSLAB_StereoCalibParams_V1 calib_params;
	if (!loadStereoCalibParams_V1(calib_xml_path, calib_params)) {
		std::cout << "[PhaseDisparityExporter] ERROR: cannot load calibration: "
		          << calib_xml_path << std::endl;
		return false;
	}

	JSLAB_PhaseEpipolarReconstructor_V2::Config rebuild_config;
	JSLAB_PhaseEpipolarReconstructor_V2 base_rebuild(rebuild_config);
	base_rebuild.setCalibrationParams(calib_params);
	base_rebuild.setData(lphase, rphase, l_k, r_k, l_mod,
	                     static_cast<int>(config.freq[0]));

	std::cout << "[PhaseDisparityExporter] Running stereo reconstruction..."
	          << std::endl;
	cv::Mat xyz, P;
	base_rebuild.startCalculate(xyz, P);

	// ---- 5. Export the disparity map ----
	cv::Mat disp;
	base_rebuild.getDisparityMap(disp);
	if (disp.empty()) {
		std::cout << "[PhaseDisparityExporter] ERROR: disparity map is empty."
		          << std::endl;
		return false;
	}

		// ---- diagnostic statistics (validity of the reconstruction) ----
	{
		const int nP = cv::countNonZero(P);
		std::cout << "[PhaseDisparityExporter] DIAG: valid P pixels = " << nP
		          << " / " << (P.cols * P.rows) << std::endl;

		cv::Mat disp_abs;
		cv::absdiff(disp, cv::Scalar::all(0), disp_abs);
		cv::Mat disp_pos;
		cv::compare(disp_abs, 0.001, disp_pos, cv::CMP_GT);
		std::cout << "[PhaseDisparityExporter] DIAG: |disp|>0 pixels = "
		          << cv::countNonZero(disp_pos) << std::endl;

		if (!P.empty() && P.size() == disp.size()) {
			double mn = 0.0, mx = 0.0;
			cv::minMaxLoc(disp, &mn, &mx, nullptr, nullptr, P);
			const cv::Scalar mean_val = cv::mean(disp, P);
			std::cout << "[PhaseDisparityExporter] DIAG: disp on P-mask: min/max/mean = "
			          << mn << " / " << mx << " / " << mean_val[0] << std::endl;
			double amn = 0.0, amx = 0.0;
			cv::minMaxLoc(disp_abs, &amn, &amx, nullptr, nullptr, P);
			const cv::Scalar amean_val = cv::mean(disp_abs, P);
			std::cout << "[PhaseDisparityExporter] DIAG: |disp| on P-mask: min/max/mean = "
			          << amn << " / " << amx << " / " << amean_val[0] << std::endl;
		}
	}

	// Valid disparity = reconstructed by the pipeline (P > 0) AND |disp| > 0.
	// NOTE: with this calibration the raw stereoMatch disparity is NEGATIVE
	// (disp = j - best_jR; the right rectified image is shifted to the right),
	// so we use |disp| for the validity mask and for the visualization, while
	// the .raw file keeps the original signed values.
	cv::Mat disp_abs;
	cv::absdiff(disp, cv::Scalar::all(0), disp_abs);
	cv::Mat disp_valid_abs;
	cv::compare(disp_abs, 0.001, disp_valid_abs, cv::CMP_GT);

	cv::Mat disp_valid;
	if (!P.empty() && P.size() == disp.size()) {
		// P is 0/1; binarize it to 0/255 so bitwise_and keeps the 255
		// semantics expected by the mask consumers below.
		cv::Mat P8;
		if (P.type() == CV_8UC1) P8 = P.clone();
		else P.convertTo(P8, CV_8UC1);
		cv::compare(P8, 0, P8, cv::CMP_GT); // 0/255
		cv::bitwise_and(disp_valid_abs, P8, disp_valid);
	}
	else {
		disp_valid = disp_valid_abs;
	}

	savePseudoColorMap(disp_abs, disp_valid, out_dir + "disparity.png",
	                   "Disparity Map (abs)");
	saveRaw64F(disp, out_dir + "disparity.raw",
	           out_dir + "disparity.info.txt");

	std::cout << "[PhaseDisparityExporter] Done. Output folder: " << out_dir
	          << std::endl;
	return true;
}
